import{R as e,e as a,f as n,U as o}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Friendly Captcha","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/friendly-captcha.md","filePath":"integrations/captchas/friendly-captcha.md","lastUpdated":1778045915000}'),r={name:"integrations/captchas/friendly-captcha.md"};function i(s,t,l,c,h,p){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="friendly-captcha" tabindex="-1">Friendly Captcha <a class="header-anchor" href="#friendly-captcha" aria-label="Permalink to &quot;Friendly Captcha&quot;">​</a></h1><p>Follow the below steps to connect Formie to Friendly Captcha.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Friendly Captcha</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-friendly-captcha-keys" tabindex="-1">Step 2. Get your Friendly Captcha Keys <a class="header-anchor" href="#step-2-get-your-friendly-captcha-keys" aria-label="Permalink to &quot;Step 2. Get your Friendly Captcha Keys&quot;">​</a></h3><ol><li>Go to <a href="https://friendlycaptcha.com/" target="_blank" rel="noreferrer">Friendly Captcha</a> and create an account, or sign in to an existing one.</li><li>In the dashboard, go to <strong>Applications</strong> and create a new application.</li><li>Copy the <strong>Sitekey</strong> shown for the application.</li><li>Go to <strong>API Keys</strong> and create an API key.</li><li>Copy the API key and store it somewhere safe, because Friendly Captcha only shows it once.</li></ol><h3 id="step-3-connect-formie-to-friendly-captcha" tabindex="-1">Step 3. Connect Formie to Friendly Captcha <a class="header-anchor" href="#step-3-connect-formie-to-friendly-captcha" aria-label="Permalink to &quot;Step 3. Connect Formie to Friendly Captcha&quot;">​</a></h3><ol><li>In Formie, choose <strong>API Version</strong>.</li><li>Select <strong>v2</strong> for new setups using a Friendly Captcha sitekey and API key.</li><li>Select <strong>v1 (legacy)</strong> only if you are already using Friendly Captcha v1 and have an existing site key and secret key.</li><li>Paste the <strong>Site Key</strong> into the <strong>Site Key</strong> field.</li><li>For <strong>v2</strong>, paste your Friendly Captcha API key into the second key field.</li><li>For <strong>v1</strong>, paste your legacy Friendly Captcha secret key into the second key field.</li><li>Optionally choose a <strong>Language</strong> and <strong>Start Mode</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Friendly Captcha</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the captcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Friendly Captcha relies on Formie&#39;s front-end output, so test it on the rendered form after saving your settings.</p>',11)])])}const y=e(r,[["render",i]]);export{g as __pageData,y as default};
